#undef DECL

typedef void (*kfn)(const double *, const double *, double *, double *, const double *, const double *,
                    size_t, size_t, size_t, size_t, size_t);
typedef struct { int n; kfn f, b; } cell_t;
static const cell_t cells[] = {
    { 3, radix3_z_rn1_fwd_avx2, radix3_z_rn1_bwd_avx2 },
    { 4, radix4_z_rn1_fwd_avx2, radix4_z_rn1_bwd_avx2 },
    { 5, radix5_z_rn1_fwd_avx2, radix5_z_rn1_bwd_avx2 },
    { 6, radix6_z_rn1_fwd_avx2, radix6_z_rn1_bwd_avx2 },
    { 7, radix7_z_rn1_fwd_avx2, radix7_z_rn1_bwd_avx2 },
    { 8, radix8_z_rn1_fwd_avx2, radix8_z_rn1_bwd_avx2 },
    { 9, radix9_z_rn1_fwd_avx2, radix9_z_rn1_bwd_avx2 },
    { 10, radix10_z_rn1_fwd_avx2, radix10_z_rn1_bwd_avx2 },
    { 11, radix11_z_rn1_fwd_avx2, radix11_z_rn1_bwd_avx2 },
    { 12, radix12_z_rn1_fwd_avx2, radix12_z_rn1_bwd_avx2 },
    { 13, radix13_z_rn1_fwd_avx2, radix13_z_rn1_bwd_avx2 },
    { 14, radix14_z_rn1_fwd_avx2, radix14_z_rn1_bwd_avx2 },
    { 15, radix15_z_rn1_fwd_avx2, radix15_z_rn1_bwd_avx2 },
    { 16, radix16_z_rn1_fwd_avx2, radix16_z_rn1_bwd_avx2 },
    { 17, radix17_z_rn1_fwd_avx2, radix17_z_rn1_bwd_avx2 },
    { 19, radix19_z_rn1_fwd_avx2, radix19_z_rn1_bwd_avx2 },
    { 21, radix21_z_rn1_fwd_avx2, radix21_z_rn1_bwd_avx2 },
    { 22, radix22_z_rn1_fwd_avx2, radix22_z_rn1_bwd_avx2 },
    { 23, radix23_z_rn1_fwd_avx2, radix23_z_rn1_bwd_avx2 },
    { 25, radix25_z_rn1_fwd_avx2, radix25_z_rn1_bwd_avx2 },
    { 26, radix26_z_rn1_fwd_avx2, radix26_z_rn1_bwd_avx2 },
    { 27, radix27_z_rn1_fwd_avx2, radix27_z_rn1_bwd_avx2 },
    { 29, radix29_z_rn1_fwd_avx2, radix29_z_rn1_bwd_avx2 },
    { 31, radix31_z_rn1_fwd_avx2, radix31_z_rn1_bwd_avx2 },
    { 32, radix32_z_rn1_fwd_avx2, radix32_z_rn1_bwd_avx2 },
    { 37, radix37_z_rn1_fwd_avx2, radix37_z_rn1_bwd_avx2 },
    { 41, radix41_z_rn1_fwd_avx2, radix41_z_rn1_bwd_avx2 },
    { 43, radix43_z_rn1_fwd_avx2, radix43_z_rn1_bwd_avx2 },
    { 47, radix47_z_rn1_fwd_avx2, radix47_z_rn1_bwd_avx2 },
    { 64, radix64_z_rn1_fwd_avx2, radix64_z_rn1_bwd_avx2 },
};

static double urand(unsigned *s)
{
    *s = *s * 1664525u + 1013904223u;
    return (double)(*s >> 8) / (double)(1u << 24) - 0.5;
}
static void naive_r2c(const double *x, double *X, int n)
{
    for (int k = 0; k <= n / 2; k++)
    {
        double re = 0, im = 0;
        for (int j = 0; j < n; j++)
        {
            double a = -2.0 * 3.14159265358979323846 * (double)k * (double)j / (double)n;
            re += x[j] * cos(a); im += x[j] * sin(a);
        }
        X[2 * k] = re; X[2 * k + 1] = im;
    }
}
static void naive_c2r(const double *X, double *x, int n)
{
    for (int j = 0; j < n; j++)
    {
        double s = 0;
        for (int k = 0; k < n; k++)
        {
            double re, im;
            if (k <= n / 2) { re = X[2 * k]; im = X[2 * k + 1]; }
            else { re = X[2 * (n - k)]; im = -X[2 * (n - k) + 1]; }
            double a = 2.0 * 3.14159265358979323846 * (double)k * (double)j / (double)n;
            s += re * cos(a) - im * sin(a);
        }
        x[j] = s;
    }
}
static double maxabs_rel(const double *a, const double *b, int n)
{
    double sc = 0, e = 0;
    for (int i = 0; i < n; i++) { if (fabs(b[i]) > sc) sc = fabs(b[i]); double d = fabs(a[i] - b[i]); if (d > e) e = d; }
    return sc > 0 ? e / sc : e;
}

int main(void)
{
    unsigned seed = 0x1357u;
    int fails = 0;
    for (size_t c = 0; c < sizeof cells / sizeof cells[0]; c++)
    {
        const int n = cells[c].n, h = n / 2;
        double x[2][64], Xr[2][66], X[66], y[64], yr[2][64];
        for (int r = 0; r < 2; r++) for (int i = 0; i < 64; i++) x[r][i] = urand(&seed);
        for (int r = 0; r < 2; r++) { naive_r2c(x[r], Xr[r], n); Xr[r][1] = 0; if (n % 2 == 0) Xr[r][2 * h + 1] = 0; naive_c2r(Xr[r], yr[r], n); }
        /* count = 1: the K=1 solo */
        memset(X, 0, sizeof X);
        cells[c].f(x[0], 0, X, 0, 0, 0, 1, 0, 1, 0, 1);
        const double ef1 = maxabs_rel(X, Xr[0], 2 * h + 2);
        memset(y, 0, sizeof y);
        cells[c].b(Xr[0], 0, y, 0, 0, 0, 1, 0, 1, 0, 1);
        const double eb1 = maxabs_rel(y, yr[0], n);
        /* IN PLACE (zin == zout): the kind is alias-tolerant (no __restrict__, every load
         * of a loop body precedes every store); the real door's in-place placement */
        double bi[66];
        memset(bi, 0, sizeof bi); memcpy(bi, x[0], (size_t)n * sizeof(double));
        cells[c].f(bi, 0, bi, 0, 0, 0, 1, 0, 1, 0, 1);
        const double efi = maxabs_rel(bi, Xr[0], 2 * h + 2);
        memset(bi, 0, sizeof bi); memcpy(bi, Xr[0], (size_t)(2 * h + 2) * sizeof(double));
        cells[c].b(bi, 0, bi, 0, 0, 0, 1, 0, 1, 0, 1);
        const double ebi = maxabs_rel(bi, yr[0], n);
        /* count = 2: two rows per vector, Ls = OLs = 2 */
        double x2[128], X2[132], XH2[132], y2[128];
        for (int i = 0; i < n; i++) { x2[i * 2] = x[0][i]; x2[i * 2 + 1] = x[1][i]; }
        memset(X2, 0, sizeof X2);
        cells[c].f(x2, 0, X2, 0, 0, 0, 2, 0, 2, 0, 2);
        double ef2 = 0, sc = 0;
        for (int r = 0; r < 2; r++)
            for (int l = 0; l <= h; l++)
            {
                double dr = fabs(X2[2 * (l * 2 + r)] - Xr[r][2 * l]), di = fabs(X2[2 * (l * 2 + r) + 1] - Xr[r][2 * l + 1]);
                if (dr > ef2) ef2 = dr; if (di > ef2) ef2 = di;
                if (fabs(Xr[r][2 * l]) > sc) sc = fabs(Xr[r][2 * l]);
            }
        ef2 /= sc > 0 ? sc : 1;
        for (int r = 0; r < 2; r++) for (int l = 0; l <= h; l++) { XH2[2 * (l * 2 + r)] = Xr[r][2 * l]; XH2[2 * (l * 2 + r) + 1] = Xr[r][2 * l + 1]; }
        memset(y2, 0, sizeof y2);
        cells[c].b(XH2, 0, y2, 0, 0, 0, 2, 0, 2, 0, 2);
        double eb2 = 0, sy = 0;
        for (int r = 0; r < 2; r++)
            for (int l = 0; l < n; l++) { double d = fabs(y2[l * 2 + r] - yr[r][l]); if (d > eb2) eb2 = d; if (fabs(yr[r][l]) > sy) sy = fabs(yr[r][l]); }
        eb2 /= sy > 0 ? sy : 1;
        const int ok = ef1 < 1e-13 && eb1 < 1e-13 && efi < 1e-13 && ebi < 1e-13 && ef2 < 1e-13 && eb2 < 1e-13;
        if (!ok) fails++;
        printf("N=%-3d solo: r2c %.1e c2r %.1e | in place: r2c %.1e c2r %.1e | two rows: r2c %.1e c2r %.1e  %s\n", n, ef1, eb1, efi, ebi, ef2, eb2, ok ? "PASS" : "FAIL");
    }
    printf("%s\n", fails ? "FAILURES" : "ALL PASS");
    return fails ? 1 : 0;
}
